1	using System.Data;
2	using FluentValidation;
3	using Kanban.Business.Interfaces;
4	using Kanban.Business.Transforms;
5	using Kanban.Contracts;
6	using Kanban.DataAccess.Interfaces;
7	using Kanban.Domain.Entities;
8	using Kanban.Domain.Exceptions;
9	using Microsoft.AspNetCore.Authorization;
10	using Microsoft.Extensions.Logging;
11	using Polly;
12	using Polly.Retry;
13	
14	namespace Kanban.Business.Services;
15	
16	public sealed class CardService : ICardService
17	{
18	    private readonly ICardRepository _cardRepository;
19	    private readonly ILaneRepository _laneRepository;
20	    private readonly IBoardRepository _boardRepository;
21	    private readonly IBoardMemberRepository _boardMemberRepository;
22	    private readonly ICurrentUserService _currentUserService;
23	    private readonly IAuthorizationService _authorizationService;
24	    private readonly IDbConnection _dbConnection;
25	    private readonly IDbConnectionFactory _transactionFactory;
26	    private readonly ILogger<CardService> _logger;
27	
28	    private static readonly ResiliencePipeline RetryPolicy =
29	        new ResiliencePipelineBuilder()
30	            .AddRetry(new RetryStrategyOptions
31	            {
32	                MaxRetryAttempts = 5,
33	                Delay = TimeSpan.FromMilliseconds(50),
34	                BackoffType = DelayBackoffType.Exponential,
35	                UseJitter = true,
36	                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
37	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
38	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
39	            })
40	            .Build();
41	
42	    public CardService(
43	        ICardRepository cardRepository,
44	        ILaneRepository laneRepository,
45	        IBoardRepository boardRepository,
46	        IBoardMemberRepository boardMemberRepository,
47	        ICurrentUserService currentUserService,
48	        IAuthorizationService authorizationService,
49	        IDbConnection dbConnection,
50	        IDbConnectionFactory transactionFactory,
51	        ILogger<CardService> logger)
52	    {
53	        ArgumentNullException.ThrowIfNull(cardRepository);
54	        ArgumentNullException.ThrowIfNull(laneRepository);
55	        ArgumentNullException.ThrowIfNull(boardRepository);
56	        ArgumentNullException.ThrowIfNull(boardMemberRepository);
57	        ArgumentNullException.ThrowIfNull(currentUserService);
58	        ArgumentNullException.ThrowIfNull(authorizationService);
59	        ArgumentNullException.ThrowIfNull(dbConnection);
60	        ArgumentNullException.ThrowIfNull(transactionFactory);
61	        ArgumentNullException.ThrowIfNull(logger);
62	        _cardRepository = cardRepository;
63	        _laneRepository = laneRepository;
64	        _boardRepository = boardRepository;
65	        _boardMemberRepository = boardMemberRepository;
66	        _currentUserService = currentUserService;
67	        _authorizationService = authorizationService;
68	        _dbConnection = dbConnection;
69	        _transactionFactory = transactionFactory;
70	        _logger = logger;
71	    }
72	
73	    public async Task<CardDto> CreateAsync(Guid boardId, Guid laneId, CreateCardRequest request)
74	    {
75	        new InlineValidator<Guid>
76	            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
77	            .ValidateAndThrow(boardId);
78	        new InlineValidator<Guid>
79	            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }
80	            .ValidateAndThrow(laneId);
81	        new InlineValidator<CreateCardRequest>
82	            { v => v.RuleFor(x => x.Title).NotEmpty().MaximumLength(200) }
83	            .ValidateAndThrow(request);
84	
85	        var userId = _currentUserService.UserId!.Value;
86	        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
87	            ?? throw new NotFoundException("board.not_found", "Board not found.");
