import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { ApiError } from './useBoards'

interface DeleteCardVars {
  boardId: string
  cardId: string
}

async function deleteCard(vars: DeleteCardVars): Promise<void> {
  const response = await fetch(`/api/v1/boards/${vars.boardId}/cards/${vars.cardId}`, {
    method: 'DELETE',
  })
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
}

export function useDeleteCard() {
  const queryClient = useQueryClient()
  return useMutation<void, ApiError, DeleteCardVars>({
    mutationFn: deleteCard,
    onSettled: (_data, _error, { boardId }) =>
      queryClient.invalidateQueries({ queryKey: ['boards', boardId] }),
    retry: false,
  })
}

import { Button, Text, Badge, makeStyles, tokens } from '@fluentui/react-components'
import { NoteRegular } from '@fluentui/react-icons'
import type { Card } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'

const useStyles = makeStyles({
  card: {
    backgroundColor: tokens.colorNeutralBackground1,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalS,
    paddingLeft: tokens.spacingHorizontalM,
    paddingRight: tokens.spacingHorizontalS,
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: tokens.spacingHorizontalS,
    boxShadow: tokens.shadow2,
    cursor: 'default',
  },
  body: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
    flex: 1,
    minWidth: 0,
  },
  meta: {
    display: 'flex',
    alignItems: 'center',
    gap: tokens.spacingHorizontalXS,
  },
})

interface CardItemProps {
  card: Card
  callerRole: BoardRole
  onEdit: (card: Card) => void
}

export default function CardItem({ card, callerRole, onEdit }: CardItemProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'

  return (
    <article className={styles.card}>
      <div className={styles.body}>
        <Text>{card.title}</Text>
        <div className={styles.meta}>
          {card.dueDate && (
            <Badge appearance="outline" size="small">
              {card.dueDate}
            </Badge>
          )}
          {card.description && (
            <span role="img" aria-label="has description">
              <NoteRegular fontSize={14} aria-hidden="true" />
            </span>
          )}
        </div>
      </div>
      {canModify && (
        <Button
          size="small"
          appearance="subtle"
          aria-label={`Edit card ${card.title}`}
          onClick={() => onEdit(card)}
        >
          Edit
        </Button>
      )}
    </article>
  )
}

import { useState } from 'react'
import {
  Button,
  Field,
  Input,
  MessageBar,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useCreateCard } from '../../hooks/useCreateCard'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    marginTop: tokens.spacingVerticalS,
  },
  actions: {
    display: 'flex',
    gap: tokens.spacingHorizontalS,
  },
})

interface AddCardFormProps {
  boardId: string
  laneId: string
}

export default function AddCardForm({ boardId, laneId }: AddCardFormProps) {
  const styles = useStyles()
  const [open, setOpen] = useState(false)
  const [title, setTitle] = useState('')
  const createCard = useCreateCard()

  const handleSubmit = () => {
    if (!title.trim()) return
    createCard.mutate(
      { boardId, laneId, title: title.trim() },
      {
        onSuccess: () => {
          setTitle('')
          setOpen(false)
        },
      },
    )
  }

  if (!open) {
    return (
      <Button
        appearance="subtle"
        size="small"
        onClick={() => setOpen(true)}
        aria-label="Add card"
      >
        + Add card
      </Button>
    )
  }

  return (
    <div className={styles.root}>
      {createCard.isError && (
        <MessageBar role="alert" intent="error">
          Failed to add card. Please try again.
        </MessageBar>
      )}
      <Field label="Card title">
        <Input
          aria-label="Card title"
          value={title}
          onChange={(_, d) => setTitle(d.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSubmit()
            if (e.key === 'Escape') setOpen(false)
          }}
          autoFocus
        />
      </Field>
      <div className={styles.actions}>
        <Button
          appearance="primary"
          size="small"
          onClick={handleSubmit}
          disabled={createCard.isPending}
        >
          Add
        </Button>
        <Button
          appearance="subtle"
          size="small"
          onClick={() => {
            setOpen(false)
            setTitle('')
          }}
        >
          Cancel
        </Button>
      </div>
    </div>
  )
}

import { useState } from 'react'
import {
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Field,
  Input,
  MessageBar,
  Textarea,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import type { Card } from '../../hooks/useBoard'
import { useUpdateCard } from '../../hooks/useUpdateCard'
import { useDeleteCard } from '../../hooks/useDeleteCard'

const useStyles = makeStyles({
  fields: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalM,
  },
})

interface CardDetailDialogProps {
  card: Card
  open: boolean
  onClose: () => void
}

export default function CardDetailDialog({ card, open, onClose }: CardDetailDialogProps) {
  const styles = useStyles()
  const [title, setTitle] = useState(card.title)
  const [description, setDescription] = useState(card.description ?? '')
  const [dueDate, setDueDate] = useState(card.dueDate ?? '')
  const [clearDueDate, setClearDueDate] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(false)

  const updateCard = useUpdateCard()
  const deleteCard = useDeleteCard()

  const handleSave = () => {
    updateCard.mutate(
      {
        boardId: card.boardId,
        cardId: card.id,
        title,
        description: description || null,
        clearDueDate,
        dueDate: clearDueDate ? null : (dueDate || null),
      },
      { onSuccess: onClose },
    )
  }

  const handleDelete = () => {
    deleteCard.mutate(
      { boardId: card.boardId, cardId: card.id },
      { onSuccess: onClose },
    )
  }

  const isMutating = updateCard.isPending || deleteCard.isPending
  const hasError = updateCard.isError || deleteCard.isError

  if (confirmDelete) {
    return (
      <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Delete card?</DialogTitle>
            <DialogContent>
              This will permanently delete "{card.title}". This action cannot be undone.
            </DialogContent>
            <DialogActions>
              <Button
                appearance="primary"
                onClick={handleDelete}
                disabled={isMutating}
              >
                Confirm
              </Button>
              <Button appearance="subtle" onClick={() => setConfirmDelete(false)}>
                Cancel
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Edit card</DialogTitle>
          <DialogContent>
            {hasError && (
              <MessageBar role="alert" intent="error">
                Failed to save changes. Please try again.
              </MessageBar>
            )}
            <div className={styles.fields}>
              <Field label="Title" required>
                <Input
                  aria-label="Title"
                  value={title}
                  onChange={(_, d) => setTitle(d.value)}
                />
              </Field>
              <Field label="Description">
                <Textarea
                  aria-label="Description"
                  value={description}
                  onChange={(_, d) => setDescription(d.value)}
                />
              </Field>
              <Field label="Due date">
                <Input
                  aria-label="Due date"
                  type="date"
                  value={clearDueDate ? '' : dueDate}
                  onChange={(_, d) => setDueDate(d.value)}
                  disabled={clearDueDate}
                />
              </Field>
              <Checkbox
                label="Clear due date"
                checked={clearDueDate}
                onChange={(_, d) => setClearDueDate(!!d.checked)}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              onClick={handleSave}
              disabled={isMutating}
            >
              Save
            </Button>
            <Button
              appearance="outline"
              onClick={() => setConfirmDelete(true)}
              disabled={isMutating}
            >
              Delete card
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="subtle" onClick={onClose}>
                Cancel
              </Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

