file.content:
using System.Data;
using FluentValidation;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Entities;
using Kanban.Domain.Exceptions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class CardService : ICardService
{
    private readonly ICardRepository _cardRepository;
    private readonly ILaneRepository _laneRepository;
    private readonly IBoardRepository _boardRepository;
    private readonly IBoardMemberRepository _boardMemberRepository;
    private readonly ICurrentUserService _currentUserService;
    private readonly IAuthorizationService _authorizationService;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<CardService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public CardService(
        ICardRepository cardRepository,
        ILaneRepository laneRepository,
        IBoardRepository boardRepository,
        IBoardMemberRepository boardMemberRepository,
        ICurrentUserService currentUserService,
        IAuthorizationService authorizationService,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<CardService> logger)
    {
        ArgumentNullException.ThrowIfNull(cardRepository);
        ArgumentNullException.ThrowIfNull(laneRepository);
        ArgumentNullException.ThrowIfNull(boardRepository);
        ArgumentNullException.ThrowIfNull(boardMemberRepository);
        ArgumentNullException.ThrowIfNull(currentUserService);
        ArgumentNullException.ThrowIfNull(authorizationService);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _cardRepository = cardRepository;
        _laneRepository = laneRepository;
        _boardRepository = boardRepository;
        _boardMemberRepository = boardMemberRepository;
        _currentUserService = currentUserService;
        _authorizationService = authorizationService;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<CardDto> CreateAsync(Guid boardId, Guid laneId, CreateCardRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }
            .ValidateAndThrow(laneId);
        new InlineValidator<CreateCardRequest>
            { v => v.RuleFor(x => x.Title).NotEmpty().MaximumLength(200) }
            .ValidateAndThrow(request);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        _ = await _laneRepository.FindByIdAsync(laneId)
            ?? throw new NotFoundException("lane.not_found", "Lane not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.CreateCard));
        if (!auth.Succeeded)
            throw new ForbiddenException("card.create_forbidden", "You do not have permission to create cards on this board.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var count = await _cardRepository.CountInLaneAsync(laneId, tx);
                var position = count + 1;
                var now = DateTimeOffset.UtcNow;
                var card = new Card(Guid.NewGuid(), laneId, boardId, request.Title,
                    request.Description, request.DueDate, position, 1, now, now);
                await _cardRepository.InsertAsync(card, tx);

                tx.Commit();
                _logger.LogInformation("Card {CardId} created in lane {LaneId} on board {BoardId} by user {UserId}",
                    card.Id, laneId, boardId, userId);
                return CardTransforms.ToDto(card);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task<CardDto> UpdateAsync(Guid boardId, Guid cardId, UpdateCardRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }
            .ValidateAndThrow(cardId);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var card = await _cardRepository.FindByIdAsync(cardId)
            ?? throw new NotFoundException("card.not_found", "Card not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.UpdateCard));
        if (!auth.Succeeded)
            throw new ForbiddenException("card.update_forbidden", "You do not have permission to update cards on this board.");

        var newTitle = request.Title ?? card.Title;
        var newDescription = request.Description;
        var newDueDate = request.ClearDueDate ? null : (request.DueDate ?? card.DueDate);

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                card.Update(newTitle, newDescription, newDueDate, DateTimeOffset.UtcNow);
                await _cardRepository.UpdateAsync(card, tx);

                tx.Commit();
                return CardTransforms.ToDto(card);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task<CardDto> MoveAsync(Guid boardId, Guid cardId, MoveCardRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }
            .ValidateAndThrow(cardId);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        _ = await _cardRepository.FindByIdAsync(cardId)
            ?? throw new NotFoundException("card.not_found", "Card not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.UpdateCard));
        if (!auth.Succeeded)
            throw new ForbiddenException("card.move_forbidden", "You do not have permission to move cards on this board.");

        var targetLaneId = request.TargetLaneId;
        var newPosition = request.TargetPosition;

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                // Re-read current card state per attempt so retry shifts use fresh positions.
                var current = await _cardRepository.FindByIdAsync(cardId, tx)
                    ?? throw new NotFoundException("card.not_found", "Card not found.");
                var currentSourceLaneId = current.LaneId;
                var currentOldPosition = current.Position;
                var isCrossLane = currentSourceLaneId != targetLaneId;

                await _cardRepository.ParkCardAsync(cardId, tx);

                if (isCrossLane)
                    await _cardRepository.ShiftPositionsInLaneAsync(targetLaneId, newPosition, int.MaxValue, 1, tx);
                else if (newPosition < currentOldPosition)
                    await _cardRepository.ShiftPositionsInLaneAsync(currentSourceLaneId, newPosition, currentOldPosition - 1, 1, tx);
                else if (newPosition > currentOldPosition)
                    await _cardRepository.ShiftPositionsInLaneAsync(currentSourceLaneId, currentOldPosition + 1, newPosition, -1, tx);

                var rowsAffected = await _cardRepository.UpdatePositionAsync(
                    cardId, targetLaneId, newPosition, request.ExpectedVersion, tx);
                if (rowsAffected == 0)
                    throw new ConflictException("card.version_conflict",
                        "The card was modified by another user. Please refresh and try again.");

                if (isCrossLane)
                    await _cardRepository.ShiftPositionsInLaneAsync(currentSourceLaneId, currentOldPosition + 1, int.MaxValue, -1, tx);

                var updated = await _cardRepository.FindByIdAsync(cardId, tx)
                    ?? throw new NotFoundException("card.not_found", "Card not found after move.");

                tx.Commit();
                _logger.LogInformation("Card {CardId} moved to lane {LaneId} position {Position} on board {BoardId} by user {UserId}",
                    cardId, targetLaneId, newPosition, boardId, userId);
                return CardTransforms.ToDto(updated);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task DeleteAsync(Guid boardId, Guid cardId)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }
            .ValidateAndThrow(cardId);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var card = await _cardRepository.FindByIdAsync(cardId)
            ?? throw new NotFoundException("card.not_found", "Card not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.DeleteCard));
        if (!auth.Succeeded)
            throw new ForbiddenException("card.delete_forbidden", "You do not have permission to delete cards on this board.");

        var deletedPosition = card.Position;
        var laneId = card.LaneId;

        await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                await _cardRepository.DeleteAsync(cardId, tx);
                await _cardRepository.ShiftPositionsInLaneAsync(laneId, deletedPosition + 1, int.MaxValue, -1, tx);

                tx.Commit();
                _logger.LogInformation("Card {CardId} deleted from lane {LaneId} on board {BoardId} by user {UserId}",
                    cardId, laneId, boardId, userId);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }
}

using System.Data;
using Dapper;
using FluentValidation;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;

namespace Kanban.DataAccess.Repositories;

public sealed class CardRepository : ICardRepository
{
    private readonly IDbConnection _connection;

    public CardRepository(IDbConnection connection)
    {
        ArgumentNullException.ThrowIfNull(connection);
        _connection = connection;
    }

    public async Task<IReadOnlyList<Card>> FindByLaneAsync(Guid laneId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);

        const string sql = """
            SELECT id, lane_id AS LaneId, board_id AS BoardId, title, description, due_date AS DueDate,
                   position, version, created_at AS CreatedAt, updated_at AS UpdatedAt
            FROM cards
            WHERE lane_id = @laneId
            ORDER BY position ASC
            """;

        var results = await _connection.QueryAsync<Card>(
            sql, new { laneId = laneId.ToString("D") }, transaction: tx);
        return results.AsList();
    }

    public async Task<Card?> FindByIdAsync(Guid cardId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }.ValidateAndThrow(cardId);

        const string sql = """
            SELECT id, lane_id AS LaneId, board_id AS BoardId, title, description, due_date AS DueDate,
                   position, version, created_at AS CreatedAt, updated_at AS UpdatedAt
            FROM cards
            WHERE id = @cardId
            """;

        return await _connection.QuerySingleOrDefaultAsync<Card>(
            sql, new { cardId = cardId.ToString("D") }, transaction: tx);
    }

    public async Task InsertAsync(Card card, IDbTransaction tx)
    {
        ArgumentNullException.ThrowIfNull(card);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            INSERT INTO cards (id, lane_id, board_id, title, description, due_date,
                               position, version, created_at, updated_at)
            VALUES (@id, @laneId, @boardId, @title, @description, @dueDate,
                    @position, @version, @createdAt, @updatedAt)
            """;

        await _connection.ExecuteAsync(sql, new
        {
            id = card.Id.ToString("D"),
            laneId = card.LaneId.ToString("D"),
            boardId = card.BoardId.ToString("D"),
            title = card.Title,
            description = card.Description,
            dueDate = card.DueDate?.ToString("o"),
            position = card.Position,
            version = card.Version,
            createdAt = card.CreatedAt.ToString("o"),
            updatedAt = card.UpdatedAt.ToString("o"),
        }, transaction: tx);
    }

    public async Task UpdateAsync(Card card, IDbTransaction tx)
    {
        ArgumentNullException.ThrowIfNull(card);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE cards
            SET title = @title, description = @description, due_date = @dueDate, updated_at = @updatedAt
            WHERE id = @id
            """;

        await _connection.ExecuteAsync(sql, new
        {
            id = card.Id.ToString("D"),
            title = card.Title,
            description = card.Description,
            dueDate = card.DueDate?.ToString("o"),
            updatedAt = card.UpdatedAt.ToString("o"),
        }, transaction: tx);
    }

    public async Task<int> UpdatePositionAsync(Guid cardId, Guid laneId, int newPosition, int expectedVersion, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }.ValidateAndThrow(cardId);
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE cards
            SET lane_id = @laneId, position = @newPosition, version = version + 1,
                updated_at = @updatedAt
            WHERE id = @cardId
              AND version = @expectedVersion
            """;

        return await _connection.ExecuteAsync(sql, new
        {
            cardId = cardId.ToString("D"),
            laneId = laneId.ToString("D"),
            newPosition,
            expectedVersion,
            updatedAt = DateTimeOffset.UtcNow.ToString("o"),
        }, transaction: tx);
    }

    public async Task ParkCardAsync(Guid cardId, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }.ValidateAndThrow(cardId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "UPDATE cards SET position = 0 WHERE id = @cardId";
        await _connection.ExecuteAsync(sql, new { cardId = cardId.ToString("D") }, transaction: tx);
    }

    public async Task ShiftPositionsInLaneAsync(Guid laneId, int fromPosition, int toPosition, int delta, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        // Two-phase approach to avoid SQLite UNIQUE constraint violations on (lane_id, position).
        // Phase 1: park affected rows at their negated positions (negative values are always free
        //          because the domain only ever inserts positive positions >= 1).
        // Phase 2: finalize from negative to target value using -position + delta.
        const string parkSql = """
            UPDATE cards
            SET position = -position
            WHERE lane_id = @laneId
              AND position >= @fromPosition
              AND position <= @toPosition
            """;

        const string finalizeSql = """
            UPDATE cards
            SET position = -position + @delta
            WHERE lane_id = @laneId
              AND position >= @negToPosition
              AND position <= @negFromPosition
            """;

        var laneIdStr = laneId.ToString("D");
        await _connection.ExecuteAsync(parkSql, new
        {
            laneId = laneIdStr,
            fromPosition,
            toPosition,
        }, transaction: tx);

        await _connection.ExecuteAsync(finalizeSql, new
        {
            laneId = laneIdStr,
            negToPosition = -toPosition,
            negFromPosition = -fromPosition,
            delta,
        }, transaction: tx);
    }

    public async Task DeleteAsync(Guid cardId, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("cardId") }.ValidateAndThrow(cardId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "DELETE FROM cards WHERE id = @cardId";
        await _connection.ExecuteAsync(sql,
            new { cardId = cardId.ToString("D") }, transaction: tx);
    }

    public async Task<int> CountInLaneAsync(Guid laneId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);

        const string sql = "SELECT COUNT(*) FROM cards WHERE lane_id = @laneId";
        return await _connection.QuerySingleAsync<int>(
            sql, new { laneId = laneId.ToString("D") }, transaction: tx);
    }
}

import { useState } from 'react'
import {
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Field,
  Input,
  MessageBar,
  Textarea,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import type { Card } from '../../hooks/useBoard'
import { useUpdateCard } from '../../hooks/useUpdateCard'
import { useDeleteCard } from '../../hooks/useDeleteCard'

const useStyles = makeStyles({
  fields: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalM,
  },
})

interface CardDetailDialogProps {
  card: Card
  open: boolean
  onClose: () => void
}

export default function CardDetailDialog({ card, open, onClose }: CardDetailDialogProps) {
  const styles = useStyles()
  const [title, setTitle] = useState(card.title)
  const [description, setDescription] = useState(card.description ?? '')
  const [dueDate, setDueDate] = useState(card.dueDate ?? '')
  const [clearDueDate, setClearDueDate] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(false)

  const updateCard = useUpdateCard()
  const deleteCard = useDeleteCard()

  const handleSave = () => {
    updateCard.mutate(
      {
        boardId: card.boardId,
        cardId: card.id,
        title,
        description: description || null,
        clearDueDate,
        dueDate: clearDueDate ? null : (dueDate || null),
      },
      { onSuccess: onClose },
    )
  }

  const handleDelete = () => {
    deleteCard.mutate(
      { boardId: card.boardId, cardId: card.id },
      { onSuccess: onClose },
    )
  }

  const isMutating = updateCard.isPending || deleteCard.isPending
  const hasError = updateCard.isError || deleteCard.isError

  if (confirmDelete) {
    return (
      <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Delete card?</DialogTitle>
            <DialogContent>
              This will permanently delete "{card.title}". This action cannot be undone.
            </DialogContent>
            <DialogActions>
              <Button
                appearance="primary"
                onClick={handleDelete}
                disabled={isMutating}
              >
                Confirm
              </Button>
              <Button appearance="subtle" onClick={() => setConfirmDelete(false)}>
                Cancel
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Edit card</DialogTitle>
          <DialogContent>
            {hasError && (
              <MessageBar role="alert" intent="error">
                Failed to save changes. Please try again.
              </MessageBar>
            )}
            <div className={styles.fields}>
              <Field label="Title" required>
                <Input
                  aria-label="Title"
                  value={title}
                  onChange={(_, d) => setTitle(d.value)}
                />
              </Field>
              <Field label="Description">
                <Textarea
                  aria-label="Description"
                  value={description}
                  onChange={(_, d) => setDescription(d.value)}
                />
              </Field>
              <Field label="Due date">
                <Input
                  aria-label="Due date"
                  type="date"
                  value={clearDueDate ? '' : dueDate}
                  onChange={(_, d) => setDueDate(d.value)}
                  disabled={clearDueDate}
                />
              </Field>
              <Checkbox
                label="Clear due date"
                checked={clearDueDate}
                onChange={(_, d) => setClearDueDate(!!d.checked)}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              onClick={handleSave}
              disabled={isMutating}
            >
              Save
            </Button>
            <Button
              appearance="outline"
              onClick={() => setConfirmDelete(true)}
              disabled={isMutating}
            >
              Delete card
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="subtle" onClick={onClose}>
                Cancel
              </Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

import { useState } from 'react'
import {
  Button,
  Field,
  Input,
  MessageBar,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useCreateCard } from '../../hooks/useCreateCard'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    marginTop: tokens.spacingVerticalS,
  },
  actions: {
    display: 'flex',
    gap: tokens.spacingHorizontalS,
  },
})

interface AddCardFormProps {
  boardId: string
  laneId: string
}

export default function AddCardForm({ boardId, laneId }: AddCardFormProps) {
  const styles = useStyles()
  const [open, setOpen] = useState(false)
  const [title, setTitle] = useState('')
  const createCard = useCreateCard()

  const handleSubmit = () => {
    if (!title.trim()) return
    createCard.mutate(
      { boardId, laneId, title: title.trim() },
      {
        onSuccess: () => {
          setTitle('')
          setOpen(false)
        },
      },
    )
  }

  if (!open) {
    return (
      <Button
        appearance="subtle"
        size="small"
        onClick={() => setOpen(true)}
        aria-label="Add card"
      >
        + Add card
      </Button>
    )
  }

  return (
    <div className={styles.root}>
      {createCard.isError && (
        <MessageBar role="alert" intent="error">
          Failed to add card. Please try again.
        </MessageBar>
      )}
      <Field label="Card title">
        <Input
          aria-label="Card title"
          value={title}
          onChange={(_, d) => setTitle(d.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSubmit()
            if (e.key === 'Escape') setOpen(false)
          }}
          autoFocus
        />
      </Field>
      <div className={styles.actions}>
        <Button
          appearance="primary"
          size="small"
          onClick={handleSubmit}
          disabled={createCard.isPending}
        >
          Add
        </Button>
        <Button
          appearance="subtle"
          size="small"
          onClick={() => {
            setOpen(false)
            setTitle('')
          }}
        >
          Cancel
        </Button>
      </div>
    </div>
  )
}

