3	namespace Kanban.Domain.Entities;
4	
5	public sealed class Lane
6	{
7	    public Guid Id { get; }
8	    public Guid BoardId { get; }
9	    public string Name { get; private set; }
10	    public int Position { get; private set; }
11	    public int Version { get; private set; }
12	    public DateTimeOffset CreatedAt { get; }
13	
